interface ConfigT {
  /**
   * 输出接口/信号源列表显示 槽位号-接口号
   */
  outputInfo?: string;
  /**
   * 信号源是否显示音源设置
   */
  isShowAudioSetting?: boolean;
  /**
   * 台标设置
   */
  tvSignSetting?: false | { text?: boolean; image?: boolean };
  /**
   * 视频流回显方式 canvas | flv
   */
  videoCompType?: 'canvas' | 'flv';
  /**
   * 是否隐藏屏幕亮度
   */
  isHideBrightness?: boolean;
  /**
   * OSD设置
   */
  osdSetting?: false | { text?: boolean; image?: boolean };
  /**
   * 文字OSD大小
   */
  osdTextSize?: {
    min_x?: number;
    min_y?: number;
    max_x?: number;
    max_y?: number;
    min_w?: number;
    min_h?: number;
    max_w?: number;
    max_h?: number;
  };
  /**
   * 是否隐藏BKG设置
   */
  isHideBkg?: boolean;
  /**
   * 自定义图层布局最大个数
   */
  maxLayerLayoutNum?: number;
  /**
   * 是否显示音量调节
   */
  isShowAudioControl?: boolean;
  /**
   * 是否隐藏预编模式
   */
  isHidePreviewMode?: boolean;
  /**
   * 是否显示图层音频
   */
  isShowLayerAudio?: boolean;
  /**
   * 是否隐藏图层冻结
   */
  isHideLayerFreeze?: boolean;
  /**
   * 编辑区域内最大回显路数
   */
  maxVideoNum?: number;
  /**
   * flv流畅性(flv播放丢帧)
   */
  isFlvFluency?: boolean;
  /**
   * 画布大小
   */
  canvasSize?: {
    w: number;
    h: number;
  };
}
